insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('BF', 'BF-P-10-ND', 'Logement et hébergement 10 %, non déductible (art. 319)', '{}'::jsonb, 'Dépenses de logement ou d''hébergement facturées par un établissement hôtelier agréé, exclues du droit à déduction', 'percent', 10, 'purchase', 'domestic', date '2025-01-01', null, 'Code général des impôts, art. 319, 2) — exclusion du droit à déduction des dépenses de logement ou d''hébergement, à l''exception de celles profitant au personnel chargé de la surveillance ou de la sécurité des unités industrielles ou des chantiers. La taxe est une part du coût de ce qui a été acheté', 'S', null, 140, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 318-1) — la TVA ayant grevé les éléments du prix d''une opération imposable est déductible ; art. 321 — déduction totale lorsque le bien concourt à des affaires taxables ; art. 326 — la TVA doit être mentionnée distinctement sur la facture ; art. 317 pour le taux', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 318-3) — déduction d''une fraction de la taxe ayant grevé le coût des immobilisations ; art. 325 — régularisation lorsque le pourcentage de déduction varie de plus de 10 points ; art. 326 pour le droit à déduction', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-P-18-ND', 'Achat 18 % non déductible (art. 319)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 319 — exclusions du droit à déduction, notamment 1) les véhicules de tourisme ou à usage mixte de 3 à 9 places assises hors exceptions (revente, location professionnelle, transport public, auto-école), 3) les dépenses de réception, de restaurant, de spectacles et de déplacement, hors dépenses de transport du personnel sous contrat permanent, 4) les objets mobiliers de décoration hors mobilier commercial, industriel ou de bureau, 5) les biens cédés et services rendus à titre gratuit ou à prix très inférieur (cadeaux de plus de 10 000 F hors taxe), 6) le super carburant, le gas-oil et le biocarburant, dans la rédaction de la loi de finances pour 2025 (art. 32). La taxe est une part du coût de ce qui a été acheté', 'S', null, 150, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 318-1) et 321 — déduction de la taxe supportée sur les services acquis pour la réalisation d''affaires taxables ; art. 326 — la taxe doit être mentionnée distinctement sur la facture ; art. 317 pour le taux', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-P-IMP-18', 'Importation 18 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'import', date '2017-12-20', null, 'Code général des impôts, art. 315, 3° et art. 316-4) — le fait générateur et l''exigibilité d''une importation sont constitués par la mise à la consommation de la marchandise au sens douanier ; art. 326 — pour être déductible, la taxe doit avoir été acquittée et figurer sur la déclaration de mise à la consommation', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-P-NR-18', 'Prestations de services rendues par un non-résident 18 %, TVA autoliquidée', '{}'::jsonb, 'Importations de biens immatériels ou prestations de services rendues par un prestataire non établi au Burkina Faso : la taxe est autoliquidée sur la déclaration mensuelle de l''acquéreur, sans déclaration séparée', 'percent', 18, 'purchase', 'foreign_services_received', date '2017-12-20', null, 'Code général des impôts, art. 315, 4° — le fait générateur d''une importation de bien immatériel ou d''une prestation de services rendue par un non-résident est l''émission de la facture ou la comptabilisation de l''opération ; art. 316-4), second alinéa — l''exigibilité intervient à l''émission de la facture ; art. 334-3) — « la TVA est autoliquidée sur la déclaration mensuelle », sans formulaire distinct ; art. 318-1) et 321 pour le droit à déduction, dont aucune exclusion de l''art. 319 ne restreint cette opération. La taxe collectée pour compte propre attend son solde au compte 4478, immédiatement récupérable dans la même déclaration', null, null, 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-S-10-AIR', 'Transport aérien national 10 %', '{}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2025-01-01', null, 'Code général des impôts, art. 317, alinéa 2, dans la rédaction de la loi de finances pour 2025 (loi n° 042-2024/ALT du 26 décembre 2024, art. 31) — taux réduit à 10 % pour les transports aériens nationaux, en vigueur au 1er janvier 2025. Ce service ne figure pas dans la liste communautaire de l''art. 29 nouveau de la directive n° 02/2009/CM/UEMOA, qui autorise un taux réduit sur au plus dix biens ou services d''une liste fermée : écart apparent entre le choix national et le texte communautaire chargé ici, à signaler', 'S', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2025', null, null, null, null),
  ('BF', 'BF-S-10-HEB', 'Hébergement et restauration agréés 10 %', '{}'::jsonb, 'Prestations d''hébergement et de restauration fournies par les hôtels, les restaurants et organismes assimilés agréés', 'percent', 10, 'sale', 'domestic', date '2025-01-01', null, 'Code général des impôts, art. 317, alinéa 2, dans la rédaction de la loi de finances pour 2025 (loi n° 042-2024/ALT du 26 décembre 2024, art. 31) — « Ce taux est réduit à 10 % pour les prestations d''hébergement et de restauration fournies par les hôtels, les restaurants et organismes assimilés agréés », en vigueur au 1er janvier 2025. Un restaurant ou un hôtel non agréé facture 18 %. Une loi antérieure (n° 31-2020/AN du 9 juillet 2020) avait déjà réduit ce taux à 10 % à compter du 1er avril 2020 pour le même champ', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2025', null, null, null, null),
  ('BF', 'BF-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens, travaux immobiliers et travaux à façon au taux normal, TVA au compte 4431', 'percent', 18, 'sale', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 317 — taux de la TVA fixé à 18 %, inchangé par la loi de finances pour 2025 (loi n° 042-2024/ALT, art. 31) ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 % ; art. 315, 1° et art. 316-1) — fait générateur et exigibilité à la livraison du bien ou du travail', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-S-18-SRV', 'Prestations de services 18 %', '{}'::jsonb, 'Prestations de services au taux normal, exigibles à l''exécution du service, TVA au compte 4432', 'percent', 18, 'sale', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 317 pour le taux ; art. 315, 2° — le fait générateur d''une prestation de services est l''accomplissement du service ; art. 316-2), première phrase — l''exigibilité est constituée par l''accomplissement du service, sauf pour les redevables soumis à l''impôt sur les bénéfices non commerciaux (voir BF-S-18-SRV-BNC)', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-S-18-SRV-BNC', 'Prestations de services 18 %, redevable soumis à l''impôt sur les bénéfices non commerciaux', '{}'::jsonb, 'Prestations de services au taux normal par un redevable relevant du régime des bénéfices non commerciaux (professions libérales notamment) : la taxe n''est exigible qu''à l''encaissement du prix', 'percent', 18, 'sale', 'domestic', date '2017-12-20', null, 'Code général des impôts, art. 317 pour le taux ; art. 316-2), seconde phrase — « en ce qui concerne les redevables soumis à l''impôt sur les bénéfices non commerciaux, l''exigibilité intervient à l''encaissement du prix des services ». Facturée, la taxe attend l''encaissement au compte 4432 « T.V.A. facturée sur prestations de services » ; encaissée, elle rejoint le compte 4431 « sur ventes » et la case TVA18, faute de compte distinct pour une taxe de service en instance de collecte dans la liste des comptes', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, true, '4432', 'cgi', null, null, null, null),
  ('BF', 'BF-S-EXO', 'Opération exonérée (art. 307)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2017-12-20', null, 'Code général des impôts, art. 307 — opérations exonérées de la TVA, numérotées 1) à 24), et art. 308 — importations et ventes de médicaments et produits pharmaceutiques d''une liste par code tarifaire ; sans droit à déduction, sauf les cas assimilés à l''exportation de l''art. 318-1) ; art. 562, 4° — la facture porte la mention « exonéré »', 'E', null, 70, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('BF', 'BF-S-EXP', 'Exportation exonérée', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2017-12-20', null, 'Code général des impôts, art. 307, 2° — exonération des exportations directes de biens matériels et immatériels, des réexportations en suite de régime douanier suspensif et des exportations de services, ainsi que des transports terrestres pour la partie réalisée à l''étranger ; art. 318-1) — ces opérations ouvrent droit à déduction dans les mêmes conditions que si elles étaient soumises à la TVA ; art. 562, 4° — la facture porte la mention « exonéré »', 'G', null, 60, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

