insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('BF', 'BF-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2017-12-20', null, 'Code général des impôts, art. 334-1) — tout redevable de la TVA dépose au plus tard le 20 de chaque mois une déclaration, sur un formulaire conforme au modèle de l''administration fiscale, au titre des opérations du mois précédent, y compris une déclaration « néant » ; art. 334-3) — la TVA due sur les importations de biens immatériels ou les prestations de services rendues par des non-résidents est autoliquidée sur cette même déclaration mensuelle. Le modèle officiel de l''imprimé n''est publié dans aucune source chargée ici : les cases suivent le contenu que les articles 315 à 334 imposent de déclarer et de déduire, et non la numérotation propre de l''imprimé. Seuls les redevables réels déposent cette déclaration ; les contribuables du régime simplifié d''imposition et de la contribution des micro-entreprises sont exonérés de TVA sauf option (art. 307-1-a), et n''en déposent aucune.', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Code général des impôts, art. 334-1) — déclaration déposée « au plus tard le 20 de chaque mois », au titre des opérations du mois précédent, y compris en l''absence d''opération imposable.', 'cgi', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
